-- MP-0017: guarded editorial content import. Deploy portraits before applying.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='dap' and type='party') then raise exception 'MP-0017: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='pkr' and type='party') then raise exception 'MP-0017: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('ramkarpal-singh','sim-tze-tzin','muhammad-bakhtiar-wan-chik') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0017: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('bukit gelugor','bayan baru','balik pulau') and slug not in ('ramkarpal-singh','sim-tze-tzin','muhammad-bakhtiar-wan-chik')) then raise exception 'MP-0017: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0017:%' and (m.source_type <> 'editorial' or e.slug not in ('ramkarpal-singh','sim-tze-tzin','muhammad-bakhtiar-wan-chik') or m.import_key not like 'MP-0017:' || e.slug || ':%')) then raise exception 'MP-0017: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'ramkarpal-singh','Ramkarpal Singh','government','Member of the Dewan Rakyat','Bukit Gelugor','Pulau Pinang','Ramkarpal Singh represents Bukit Gelugor, Pulau Pinang, in the Dewan Rakyat. A DAP member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4090','/portraits/ramkarpal-singh.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P051.png','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4090"}, {"label": "DAP · representatives", "url": "https://dapmalaysia.org/pulau-pinang-representatives/"}]'::jsonb from public.entities parent where parent.slug='dap' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'sim-tze-tzin','Sim Tze Tzin','government','Deputy Minister of Investment, Trade and Industry','Bayan Baru','Pulau Pinang','Sim Tze Tzin represents Bayan Baru, Pulau Pinang, in the Dewan Rakyat. Current role: Deputy Minister of Investment, Trade and Industry. A PKR member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4091','/portraits/sim-tze-tzin.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P052.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4091"}, {"label": "PKR · representatives", "url": "https://keadilanrakyat.org/wakil-rakyat/"}]'::jsonb from public.entities parent where parent.slug='pkr' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'muhammad-bakhtiar-wan-chik','Muhammad Bakhtiar Wan Chik','government','Member of the Dewan Rakyat','Balik Pulau','Pulau Pinang','Muhammad Bakhtiar Wan Chik represents Balik Pulau, Pulau Pinang, in the Dewan Rakyat. A PKR member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4092','/portraits/muhammad-bakhtiar-wan-chik.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P053.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4092"}, {"label": "PKR · representatives", "url": "https://keadilanrakyat.org/wakil-rakyat/"}]'::jsonb from public.entities parent where parent.slug='pkr' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('ramkarpal-singh','sim-tze-tzin','muhammad-bakhtiar-wan-chik') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0017: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0017:ramkarpal-singh:ag-pp-appointment-accountability','Strengthen accountability in appointment arrangements for separated AG and prosecutor roles','Governance','in_progress',null,null,'2026-03-05','https://dapmalaysia.org/cn/2026/03/05/%E4%BF%83%E6%9F%A5%E4%BC%81%E4%B8%9A%E9%BB%91%E6%89%8B%E5%85%9A%EF%BC%8C%E9%87%8D%E6%8F%90%E9%A6%96%E7%9B%B8%E4%BB%BB%E6%9C%9F%E9%99%90%E5%88%B6%E6%B3%95%E6%A1%88-%E6%B0%91%E4%B8%BB%E8%A1%8C%E5%8A%A8/','2026-03-05','https://dapmalaysia.org/cn/2026/03/05/%E4%BF%83%E6%9F%A5%E4%BC%81%E4%B8%9A%E9%BB%91%E6%89%8B%E5%85%9A%EF%BC%8C%E9%87%8D%E6%8F%90%E9%A6%96%E7%9B%B8%E4%BB%BB%E6%9C%9F%E9%99%90%E5%88%B6%E6%B3%95%E6%A1%88-%E6%B0%91%E4%B8%BB%E8%A1%8C%E5%8A%A8/','DAP committed to pursue improvements through its select-committee representatives, including Ramkarpal Singh.','This is a shared party and parliamentary-committee commitment. The statement supports scrutiny of the bill; it does not establish enactment, appointments or a completed reform. No numerical progress was verified.','2026-11-09','editorial',false from public.entities e where e.slug='ramkarpal-singh' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0017:sim-tze-tzin:malaysia-korea-fta','Work towards signing the Malaysia–Korea Free Trade Agreement','Economy',null,null,null,'2026-01-27','https://www.miti.gov.my/miti/resources/Speech/Keynote_Speech_-_TP_YBTM_-_Trade_Performance_2025.pdf',null,null,'In a speech delivered on behalf of the minister, Sim said MITI looked towards signing the agreement by mid-2026.','The October 2025 statement concluded negotiations; it is not treated as proof of later signing or entry into force. A matching signed-agreement outcome was not verified. Mid-year supplies no exact deadline date.','2026-11-09','editorial',false from public.entities e where e.slug='sim-tze-tzin' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0017:sim-tze-tzin:national-ev-chargers','Expand the national public EV-charging network towards 10,000 points','Infrastructure','in_progress',null,null,'2026-04-02','https://www.miti.gov.my/miti/resources/Speech/%5BFINAL%5D_Speech_-_Toyota_BEV_Launch_by_YB_Deputy_Minister.pdf','2026-04-02','https://www.miti.gov.my/miti/resources/Speech/%5BFINAL%5D_Speech_-_Toyota_BEV_Launch_by_YB_Deputy_Minister.pdf','Sim described the government’s charging-infrastructure target while speaking at Toyota’s battery-electric vehicle launch.','The speech reports more than 5,000 public points, not an exact comparable numerator. No 50% completion is inferred. This is shared national infrastructure, with no new deadline specified in this speech.','2026-11-09','editorial',false from public.entities e where e.slug='sim-tze-tzin' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

